input.command:
gh api graphql -f query='
query {
  repository(owner: "ZimmermannAU", name: "zimmermann-pwa") {
    pullRequest(number: 70) {
      reviewThreads(first: 50) {
        nodes {
          isResolved
          isOutdated
          path
          line
          comments(first: 10) {
            nodes {
              author { login }
              body
              createdAt
            }
          }
        }
      }
    }
  }
}' 2>&1 | python3 -c "
import json,sys
data = json.load(sys.stdin)
threads = data['data']['repository']['pullRequest']['reviewThreads']['nodes']
for t in threads:
    print('---')
    print('resolved:', t['isResolved'], 'outdated:', t['isOutdated'], 'path:', t['path'], 'line:', t['line'])
    for c in t['comments']['nodes']:
        print('  >', c['author']['login'] if c['author'] else 'unknown', '-', c['createdAt'])
        print('    ', c['body'][:300].replace(chr(10), ' '))
"

gh api graphql -f query='
query {
  repository(owner: "ZimmermannAU", name: "zimmermann-pwa") {
    pullRequest(number: 70) {
      reviewThreads(first: 50) {
        nodes {
          isResolved
          path
          line
          comments(first: 5) {
            nodes {
              author { login }
              body
            }
          }
        }
      }
    }
  }
}' 2>&1 | python3 -c "
import json,sys
data = json.load(sys.stdin)
threads = data['data']['repository']['pullRequest']['reviewThreads']['nodes']
for t in threads:
    if t['isResolved']:
        continue
    print('=====')
    print('path:', t['path'], 'line:', t['line'])
    for c in t['comments']['nodes']:
        print('  >', c['author']['login'] if c['author'] else 'unknown')
        print('    ', c['body'])
"

